sys_ux_data_broker_transform.script:
function transform(input) {
    var kpiProperties = ["costcenter.dashboard"];
    var kpiValues = {
        'kpi_data': []
    };

    function fetchKPIs(propertyName) {
        var kpis = [];
        var propertyValue = gs.getProperty(propertyName); // Fetch system property

        if (propertyValue) {
            try {
                gs.info("Raw property value for " + propertyName + ": " + propertyValue);
                kpis = JSON.parse(propertyValue);
            } catch (e) {
                gs.info("Error parsing " + propertyName + ": " + e.message);
            }
        } else {
            gs.info("Property " + propertyName + " is not set or is empty.");
        }
        return kpis;
    }

    function processKPI(kpis) {
        if (Array.isArray(kpis.output)) {
            kpis.output.forEach(function (kpi) {
                kpiValues.kpi_data.push({
                    "name": kpi.kpi || "Unknown KPI",
                    "count": kpi.count || 0
                });
            });
            gs.info("Processed KPI values: " + JSON.stringify(kpiValues.kpi_data));
        } else {
            gs.info("Invalid KPI format: Expected an array but got " + typeof kpis.output);
        }
    }

    kpiProperties.forEach(function (property) {
        var kpiData = fetchKPIs(property);
        processKPI(kpiData);
    });

    kpiValues['kpi_data'] = [
        {
            "data": kpiValues.kpi_data.map(kpi => ({
                "assignment_group": kpi.name,
                "value": kpi.count
            })),
            "metadata": {
                "dataSourceLabel": "Incident",
                "eventData": {
                    "table": "incident"
                },
                "groupBy": [
                    {
                        "series": [
                            {
                                "id": "value",
                                "type": "value",
                                "label": "Incident"
                            }
                        ],
                        "elements": [
                            {
                                "eventData": {
                                    "query": "assignment_group=287ee6fea9fe198100ada7950d0b1b73"
                                },
                                "id": "287ee6fea9fe198100ada7950d0b1b73",
                                "label": "Database"
                            }
                        ],
                        "id": "assignment_group",
                        "fieldType": "reference",
                        "label": "Assignment group"
                    }
                ],
                "format": {
                    "unitFormat": "{0}"
                },
                "aggregateBy": 4,
                "metricId": "ZEdGaWJHVnBibU5wWkdWdWRERTJORFl5TXpRMk5qYzBORE09MTY0NjIzNDY2OTQzMw=="
            }
        }
    ];

    return kpiValues;
}
